import { useLayoutEffect, useRef, useState, type ReactNode, type RefObject } from "react";

/**
 * The width of the product card (`.h-visual`) around `ref`, null until it is
 * measured. A scene framed for a small card uses it to step back to a wider
 * framing in a card wider than that scene, where Stage would otherwise show
 * the scene 1:1 with more of the window around it than the framing allows.
 */
export function useCardWidth(ref: RefObject<HTMLElement>): number | null {
  const [width, setWidth] = useState<number | null>(null);
  useLayoutEffect(() => {
    const card = ref.current?.closest<HTMLElement>(".h-visual");
    if (!card) return;
    const update = () => setWidth(card.clientWidth);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(card);
    return () => observer.disconnect();
  }, [ref]);
  return width;
}

interface StageProps {
  /** Design size of the scene in CSS pixels; the scene is laid out at this size. */
  width: number;
  height: number;
  className?: string;
  children: ReactNode;
}

interface Fit {
  scale: number;
  /** Horizontal offset that centres the scene when the card is wider than it. */
  left: number;
}

/**
 * Lays a product scene out at its real pixel size (so the app UI keeps the
 * app's exact metrics) and shrinks it uniformly to fit a narrower card, like
 * an image would. It never grows past its real size: in a wider card it stays
 * 1:1, centred, and the card is as tall as the scene.
 */
export default function Stage({ width, height, className = "", children }: StageProps) {
  const ref = useRef<HTMLDivElement>(null);
  // null until the box is measured: the server can't know the card width, so
  // the scene stays hidden for that first frame instead of flashing unscaled.
  const [fit, setFit] = useState<Fit | null>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const update = () => {
      const scale = Math.min(1, el.clientWidth / width);
      const left = Math.max(0, (el.clientWidth - width * scale) / 2);
      setFit((prev) => (prev && prev.scale === scale && prev.left === left ? prev : { scale, left }));
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [width]);

  return (
    <div
      ref={ref}
      className={`relative w-full ${className}`}
      // Before measuring, the box keeps the scene's shape; after, its height is the scaled scene's.
      style={fit ? { height: height * fit.scale } : { aspectRatio: `${width} / ${height}` }}
    >
      <div
        className="absolute top-0"
        style={{
          left: fit?.left ?? 0,
          width,
          height,
          transform: `scale(${fit?.scale ?? 1})`,
          transformOrigin: "0 0",
          visibility: fit ? undefined : "hidden",
        }}
      >
        {children}
      </div>
    </div>
  );
}
